import { dailyIndex } from "@/lib/daily";
import type { Locale, Localized } from "@/lib/i18n";
import data from "./data/sites.json";

// data/sites.json is generated by scripts/fetch-sites.mjs — don't edit it by
// hand; add sites, clues or corrections in scripts/sites-roster.mjs instead.

export type Site = {
  id: string;
  name: Localized;
  country: Localized | null;
  lat: number;
  lon: number;
  /** When it flourished, e.g. "c. 300 BC – AD 100". Shown during play. */
  era: Localized;
  /** What it is, without saying where. Shown during play. */
  clue: Localized;
  extract: { en: string; pt: string | null };
  wiki: { en: string; pt: string | null };
  image: { src: string; width: number; height: number };
};

// A site needs a photo and coordinates to be playable.
export const SITES = (data as (Omit<Site, "image"> & { image: Site["image"] | null })[]).filter(
  (site): site is Site => site.image !== null && site.lat !== null && site.lon !== null,
);

const byId = new Map(SITES.map((site) => [site.id, site]));

export const siteById = (id: string): Site | undefined => byId.get(id);

export function siteForDay(day: number): Site {
  return SITES[dailyIndex(SITES.length, day, "dig-site")];
}

/** "Petra, Jordan" */
export function siteLabel(site: Site, locale: Locale): string {
  const country = site.country?.[locale];
  return country ? `${site.name[locale]}, ${country}` : site.name[locale];
}
